+/** Apparent width in pixels of an aircraft of this span, at this range, through this camera. */
+export const apparentPx = (spanM: number, rangeM: number, focalPx: number): number =>
+  rangeM > 0 ? (spanM * focalPx) / rangeM : Infinity;
